// EKS Workshop Chunk: misc (5 docs)
(function() {
  window.__EKS_DOCS = window.__EKS_DOCS || {};
  Object.assign(window.__EKS_DOCS, {"misc/cloud9-access": {"id": "misc/cloud9-access", "path": "misc/cloud9-access.md", "title": "Cloud9 访问", "module": "misc", "category": "杂项指引", "crumbs": ["杂项指引", "Cloud9 访问"], "prev": "cleanup/index", "prevTitle": "清理资源", "next": "misc/migrating", "nextTitle": "迁移旧实验室环境", "content": "<header><h1>Cloud9 访问</h1></header>\n<p>如果运行 Terraform 脚本后您没有看到名为 <strong>eks-workshop</strong> 的 Cloud9 实例，请执行以下操作：</p>\n<p>更改环境下拉列表以显示<strong>所有帐户环境</strong>。\n<img alt=\"更改环境下拉列表以显示**所有帐户环境**\" src=\"assets/docs/misc/cloud9-environments.webp\" loading=\"lazy\" decoding=\"async\">\n在 <strong>Cloud9 IDE</strong> 下单击 <strong>打开</strong>。</p>\n<p>如果“打开”链接不起作用，您将需要授予您的用户对 Cloud9 实例的访问权限。</p>\n<p>从 AWS CLI 修改以下代码以使您的用户能够访问 Cloud9 实例：</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">shell</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-shell\"><code class=\"language-shell\"></code></pre></div>\n<p>需要进行两次替换：</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">text</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-text\"><code class=\"language-text\"></code></pre></div>\n<p>上述 arn 应替换为需要访问 Cloud9 实例的用户或角色的 arn。</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">text</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-text\"><code class=\"language-text\"></code></pre></div>\n<p>environment_id_from_arn 应替换为您要管理的实例的 arn 中的环境 ID。单击实例名称可以找到 arn。 arn 中最后一个冒号之后的所有内容都是环境 ID。</p>\n<p><img alt=\"cloud9-arn\" src=\"assets/docs/misc/cloud9-arn.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>在 CLI 中输入带有替换文本的代码后，您现在应该能够访问 Cloud9 实例。</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">shell</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-shell\"><code class=\"language-shell\"><span class=\"o\">{</span>\n<span class=\"w\">    </span><span class=\"s2\">\"membership\"</span>:<span class=\"w\"> </span><span class=\"o\">{</span>\n<span class=\"w\">        </span><span class=\"s2\">\"permissions\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"read-write\"</span>,\n<span class=\"w\">        </span><span class=\"s2\">\"userId\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"XXXXXXXXXXXXXXXXXXX:someone\"</span>,\n<span class=\"w\">        </span><span class=\"s2\">\"userArn\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"arn:aws:sts::111111111111:assumed-role/Admin/someone\"</span>,\n<span class=\"w\">        </span><span class=\"s2\">\"environmentId\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"environment_id_from_arn\"</span>,\n<span class=\"w\">        </span><span class=\"s2\">\"lastAccess\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"2023-04-07T09:27:56-04:00\"</span>\n\n<span class=\"o\">}</span></code></pre></div>", "html": "<header><h1>Cloud9 访问</h1></header>\n<p>如果运行 Terraform 脚本后您没有看到名为 <strong>eks-workshop</strong> 的 Cloud9 实例，请执行以下操作：</p>\n<p>更改环境下拉列表以显示<strong>所有帐户环境</strong>。\n<img alt=\"更改环境下拉列表以显示**所有帐户环境**\" src=\"assets/docs/misc/cloud9-environments.webp\" loading=\"lazy\" decoding=\"async\">\n在 <strong>Cloud9 IDE</strong> 下单击 <strong>打开</strong>。</p>\n<p>如果“打开”链接不起作用，您将需要授予您的用户对 Cloud9 实例的访问权限。</p>\n<p>从 AWS CLI 修改以下代码以使您的用户能够访问 Cloud9 实例：</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">shell</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-shell\"><code class=\"language-shell\"></code></pre></div>\n<p>需要进行两次替换：</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">text</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-text\"><code class=\"language-text\"></code></pre></div>\n<p>上述 arn 应替换为需要访问 Cloud9 实例的用户或角色的 arn。</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">text</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-text\"><code class=\"language-text\"></code></pre></div>\n<p>environment_id_from_arn 应替换为您要管理的实例的 arn 中的环境 ID。单击实例名称可以找到 arn。 arn 中最后一个冒号之后的所有内容都是环境 ID。</p>\n<p><img alt=\"cloud9-arn\" src=\"assets/docs/misc/cloud9-arn.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>在 CLI 中输入带有替换文本的代码后，您现在应该能够访问 Cloud9 实例。</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">shell</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-shell\"><code class=\"language-shell\"><span class=\"o\">{</span>\n<span class=\"w\">    </span><span class=\"s2\">\"membership\"</span>:<span class=\"w\"> </span><span class=\"o\">{</span>\n<span class=\"w\">        </span><span class=\"s2\">\"permissions\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"read-write\"</span>,\n<span class=\"w\">        </span><span class=\"s2\">\"userId\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"XXXXXXXXXXXXXXXXXXX:someone\"</span>,\n<span class=\"w\">        </span><span class=\"s2\">\"userArn\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"arn:aws:sts::111111111111:assumed-role/Admin/someone\"</span>,\n<span class=\"w\">        </span><span class=\"s2\">\"environmentId\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"environment_id_from_arn\"</span>,\n<span class=\"w\">        </span><span class=\"s2\">\"lastAccess\"</span>:<span class=\"w\"> </span><span class=\"s2\">\"2023-04-07T09:27:56-04:00\"</span>\n\n<span class=\"o\">}</span></code></pre></div>"}, "misc/major-upgrade": {"id": "misc/major-upgrade", "path": "misc/major-upgrade.md", "title": "重大升级", "module": "misc", "category": "杂项指引", "crumbs": ["杂项指引", "重大升级"], "prev": "misc/migrating", "prevTitle": "迁移旧实验室环境", "next": null, "nextTitle": null, "content": "<header><h1>重大升级</h1></header>\n<p>工作坊的某些版本构成了不向后兼容的“重大升级”。例如，升级正在使用的 EKS 版本以及 IDE 中的其他依赖项。发生这种情况时，在自己的 AWS 账户中拥有现有实验室环境的用户必须删除并重新创建该环境。</p>\n<p>按照<a href=\"/docs/introduction/setup/your-account/cleanup\">清理</a>中的说明删除EKS集群和Cloud9 IDE。</p>\n<p>接下来，按照 <a href=\"/docs/introduction/setup/your-account\">在您的 AWS 账户中</a> 部分创建新的环境，创建新的 Cloud9 IDE 和 EKS 集群。这将确保这两者都得到更新以反映最新版本以与内容保持一致。</p>\n<div class=\"theme-admonition theme-admonition-tip alert alert--success\"><div class=\"admonitionHeading alert__heading\"><span class=\"admonitionIcon alert__icon\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"currentColor\"><path d=\"M9 21c0 .55.45 1 1 1h4c.55 0 1-.45 1-1v-1H9v1zm3-19C8.14 2 5 5.14 5 9c0 2.38 1.19 4.47 3 5.74V17c0 .55.45 1 1 1h6c.55 0 1-.45 1-1v-2.26c1.81-1.27 3-3.36 3-5.74 0-3.86-3.14-7-7-7zm2.85 11.1l-.85.6V16h-4v-1.3l-.85-.6A4.997 4.997 0 0 1 7 9c0-2.76 2.24-5 5-5s5 2.24 5 5c0 1.63-.8 3.16-2.15 4.1z\"/></svg></span>TIP / 技巧</div><div class=\"admonitionContent\"><p>许多实验室可能会继续与您​​现有的实验室一起运行，但有些实验室可能会部分运行或使您的环境处于无法维护的状态。建议按照上述步骤操作。</p></div></div>", "html": "<header><h1>重大升级</h1></header>\n<p>工作坊的某些版本构成了不向后兼容的“重大升级”。例如，升级正在使用的 EKS 版本以及 IDE 中的其他依赖项。发生这种情况时，在自己的 AWS 账户中拥有现有实验室环境的用户必须删除并重新创建该环境。</p>\n<p>按照<a href=\"/docs/introduction/setup/your-account/cleanup\">清理</a>中的说明删除EKS集群和Cloud9 IDE。</p>\n<p>接下来，按照 <a href=\"/docs/introduction/setup/your-account\">在您的 AWS 账户中</a> 部分创建新的环境，创建新的 Cloud9 IDE 和 EKS 集群。这将确保这两者都得到更新以反映最新版本以与内容保持一致。</p>\n<div class=\"theme-admonition theme-admonition-tip alert alert--success\"><div class=\"admonitionHeading alert__heading\"><span class=\"admonitionIcon alert__icon\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"currentColor\"><path d=\"M9 21c0 .55.45 1 1 1h4c.55 0 1-.45 1-1v-1H9v1zm3-19C8.14 2 5 5.14 5 9c0 2.38 1.19 4.47 3 5.74V17c0 .55.45 1 1 1h6c.55 0 1-.45 1-1v-2.26c1.81-1.27 3-3.36 3-5.74 0-3.86-3.14-7-7-7zm2.85 11.1l-.85.6V16h-4v-1.3l-.85-.6A4.997 4.997 0 0 1 7 9c0-2.76 2.24-5 5-5s5 2.24 5 5c0 1.63-.8 3.16-2.15 4.1z\"/></svg></span>TIP / 技巧</div><div class=\"admonitionContent\"><p>许多实验室可能会继续与您​​现有的实验室一起运行，但有些实验室可能会部分运行或使您的环境处于无法维护的状态。建议按照上述步骤操作。</p></div></div>"}, "misc/migrating": {"id": "misc/migrating", "path": "misc/migrating.md", "title": "迁移旧实验室环境", "module": "misc", "category": "杂项指引", "crumbs": ["杂项指引", "迁移旧实验室环境"], "prev": "misc/cloud9-access", "prevTitle": "Cloud9 访问", "next": "misc/major-upgrade", "nextTitle": "重大升级", "content": "<header><h1>迁移旧实验室环境</h1></header>\n<p>2023 年 7 月 21 日，EKS Workshop 在基础设施的配置方面经历了一些重大变化。以前，工作坊将依靠 Terraform 在开始之前配置所有基础设施，因此决定进行更改以减少最初开始时可能出现的问题数量。车间基础设施现已逐步构建，并简化了初始设置。</p>\n<p>如果您有一个通过基于 Terraform 的旧机制配置的实验室环境，您将需要迁移到这个新的配置机制。以下步骤提供了清理现有环境的指南。</p>\n<p>首先，访问Cloud9 IDE并运行以下命令来清理集群中运行的示例应用程序。这是确保 Terraform 可以清理 EKS 集群和 VPC 所必需的：</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">bash</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-bash\"><code class=\"language-bash\">$<span class=\"w\"> </span>delete-environment</code></pre></div>\n<p>接下来，您应该删除 Terraform 预置的 AWS 资源。从您最初克隆的 Git 存储库（例如在本地计算机上）运行以下命令：</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">bash</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-bash\"><code class=\"language-bash\">$<span class=\"w\"> </span><span class=\"nb\">cd</span><span class=\"w\"> </span>terraform\n$<span class=\"w\"> </span>terraform<span class=\"w\"> </span>destroy<span class=\"w\"> </span>-target<span class=\"o\">=</span>module.cluster.module.eks_blueprints_kubernetes_addons<span class=\"w\"> </span>--auto-approve\n<span class=\"c1\"># To delete the descheduler add-on, run the following command:</span>\n$<span class=\"w\"> </span>terraform<span class=\"w\"> </span>destroy<span class=\"w\"> </span>-target<span class=\"o\">=</span>module.cluster.module.descheduler<span class=\"w\"> </span>--auto-approve\n<span class=\"c1\"># To delete the core blueprints add-ons, run the following command:</span>\n$<span class=\"w\"> </span>terraform<span class=\"w\"> </span>destroy<span class=\"w\"> </span>-target<span class=\"o\">=</span>module.cluster.module.eks_blueprints<span class=\"w\"> </span>--auto-approve\n<span class=\"c1\"># To delete the remaining resources created by Terraform, run the following command:</span>\n$<span class=\"w\"> </span>terraform<span class=\"w\"> </span>destroy<span class=\"w\"> </span>--auto-approve</code></pre></div>\n<p>您现在可以按照<a href=\"/docs/introduction/setup/your-account\">此处概述</a> 的步骤创建新的实验室环境。</p>", "html": "<header><h1>迁移旧实验室环境</h1></header>\n<p>2023 年 7 月 21 日，EKS Workshop 在基础设施的配置方面经历了一些重大变化。以前，工作坊将依靠 Terraform 在开始之前配置所有基础设施，因此决定进行更改以减少最初开始时可能出现的问题数量。车间基础设施现已逐步构建，并简化了初始设置。</p>\n<p>如果您有一个通过基于 Terraform 的旧机制配置的实验室环境，您将需要迁移到这个新的配置机制。以下步骤提供了清理现有环境的指南。</p>\n<p>首先，访问Cloud9 IDE并运行以下命令来清理集群中运行的示例应用程序。这是确保 Terraform 可以清理 EKS 集群和 VPC 所必需的：</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">bash</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-bash\"><code class=\"language-bash\">$<span class=\"w\"> </span>delete-environment</code></pre></div>\n<p>接下来，您应该删除 Terraform 预置的 AWS 资源。从您最初克隆的 Git 存储库（例如在本地计算机上）运行以下命令：</p>\n<div class=\"theme-code-block\"><div class=\"code-block-header\"><span class=\"code-block-lang\">bash</span><button class=\"clean-btn copy-btn\" type=\"button\" aria-label=\"复制代码\" title=\"复制代码\" onclick=\"window.copyCode(this)\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"currentColor\"><path d=\"M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z\"/></svg><span>复制</span></button></div><pre class=\"prism-code language-bash\"><code class=\"language-bash\">$<span class=\"w\"> </span><span class=\"nb\">cd</span><span class=\"w\"> </span>terraform\n$<span class=\"w\"> </span>terraform<span class=\"w\"> </span>destroy<span class=\"w\"> </span>-target<span class=\"o\">=</span>module.cluster.module.eks_blueprints_kubernetes_addons<span class=\"w\"> </span>--auto-approve\n<span class=\"c1\"># To delete the descheduler add-on, run the following command:</span>\n$<span class=\"w\"> </span>terraform<span class=\"w\"> </span>destroy<span class=\"w\"> </span>-target<span class=\"o\">=</span>module.cluster.module.descheduler<span class=\"w\"> </span>--auto-approve\n<span class=\"c1\"># To delete the core blueprints add-ons, run the following command:</span>\n$<span class=\"w\"> </span>terraform<span class=\"w\"> </span>destroy<span class=\"w\"> </span>-target<span class=\"o\">=</span>module.cluster.module.eks_blueprints<span class=\"w\"> </span>--auto-approve\n<span class=\"c1\"># To delete the remaining resources created by Terraform, run the following command:</span>\n$<span class=\"w\"> </span>terraform<span class=\"w\"> </span>destroy<span class=\"w\"> </span>--auto-approve</code></pre></div>\n<p>您现在可以按照<a href=\"/docs/introduction/setup/your-account\">此处概述</a> 的步骤创建新的实验室环境。</p>"}, "_partials/setup/aws-event-setup": {"id": "_partials/setup/aws-event-setup", "path": "_partials/setup/aws-event-setup.mdx", "title": "Aws Event Setup", "module": "misc", "category": "Partials", "crumbs": ["Partials", "Aws Event Setup"], "prev": null, "prevTitle": null, "next": null, "nextTitle": null, "content": "<header><h1>Aws Event Setup</h1></header>\n<p>通过参加本次工作坊，您将获得一个 AWS 账户，用于完成实验材料。通过浏览 <a href=\"https://catalog.workshops.aws/\">https://catalog.workshops.aws/</a> 连接到门户。单击<strong>开始</strong>。</p>\n<p><img alt=\"工坊工作室主页\" src=\"assets/docs/introduction/setup/workshop-studio-home.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>系统将提示您登录。选择选项<strong>通过电子邮件发送一次性密码(OTP)</strong>。</p>\n<p><img src=\"docs/introduction/setup/ws-studio-login.webp\" alt=\"Workshop Studio 登录\" style=\"width: 400px\" loading=\"lazy\" decoding=\"async\"></p>\n<p>输入您的电子邮件地址，然后按 <strong>发送密码</strong>，这会将一次性密码发送到您的收件箱。电子邮件到达后，输入密码并登录。</p>\n<p>在开始这些练习之前，您的教练应该为您提供<strong>活动访问代码</strong>。在文本框中输入提供的代码，然后单击<strong>下一步</strong>。</p>\n<p><img alt=\"事件代码\" src=\"assets/docs/introduction/setup/event-code.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>阅读并接受条款和条件，然后单击 <strong>加入活动</strong> 继续。</p>\n<p><img alt=\"查看并加入\" src=\"assets/docs/introduction/setup/review-and-join.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>您将看到您的个人仪表板。选择 <strong>打开 AWS 控制台</strong> 按钮以转到您的 AWS 账户控制台：</p>\n<p><img alt=\"打开控制台\" src=\"assets/docs/introduction/setup/openconsole.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>接下来，返回个人仪表板页面并向下滚动到 <strong>Event Outputs</strong> 部分。从 <strong>IdeUrl</strong> 字段复制 URL 并在新的浏览器选项卡中打开它：</p>\n<p><img alt=\"Cloud9 链接\" src=\"assets/docs/introduction/setup/workshop-studio-06.png\" loading=\"lazy\" decoding=\"async\"></p>\n<p>系统将提示您输入密码：</p>\n<p><img alt=\"IDE 密码\" src=\"assets/docs/introduction/setup/visual-studio-01.png\" loading=\"lazy\" decoding=\"async\"></p>\n<p>输入输出中 <strong>IdePassword</strong> 字段中的值，Web IDE 将加载。</p>\n<p><img alt=\"代码服务器登录画面\" src=\"assets/docs/introduction/setup/vscode-splash.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>按 <strong>开始</strong> 访问工作坊启动页面：</p>\n<p><img alt=\"开始\" src=\"assets/docs/introduction/setup/workshop-event-page.webp\" loading=\"lazy\" decoding=\"async\"></p>", "html": "<header><h1>Aws Event Setup</h1></header>\n<p>通过参加本次工作坊，您将获得一个 AWS 账户，用于完成实验材料。通过浏览 <a href=\"https://catalog.workshops.aws/\">https://catalog.workshops.aws/</a> 连接到门户。单击<strong>开始</strong>。</p>\n<p><img alt=\"工坊工作室主页\" src=\"assets/docs/introduction/setup/workshop-studio-home.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>系统将提示您登录。选择选项<strong>通过电子邮件发送一次性密码(OTP)</strong>。</p>\n<p><img src=\"docs/introduction/setup/ws-studio-login.webp\" alt=\"Workshop Studio 登录\" style=\"width: 400px\" loading=\"lazy\" decoding=\"async\"></p>\n<p>输入您的电子邮件地址，然后按 <strong>发送密码</strong>，这会将一次性密码发送到您的收件箱。电子邮件到达后，输入密码并登录。</p>\n<p>在开始这些练习之前，您的教练应该为您提供<strong>活动访问代码</strong>。在文本框中输入提供的代码，然后单击<strong>下一步</strong>。</p>\n<p><img alt=\"事件代码\" src=\"assets/docs/introduction/setup/event-code.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>阅读并接受条款和条件，然后单击 <strong>加入活动</strong> 继续。</p>\n<p><img alt=\"查看并加入\" src=\"assets/docs/introduction/setup/review-and-join.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>您将看到您的个人仪表板。选择 <strong>打开 AWS 控制台</strong> 按钮以转到您的 AWS 账户控制台：</p>\n<p><img alt=\"打开控制台\" src=\"assets/docs/introduction/setup/openconsole.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>接下来，返回个人仪表板页面并向下滚动到 <strong>Event Outputs</strong> 部分。从 <strong>IdeUrl</strong> 字段复制 URL 并在新的浏览器选项卡中打开它：</p>\n<p><img alt=\"Cloud9 链接\" src=\"assets/docs/introduction/setup/workshop-studio-06.png\" loading=\"lazy\" decoding=\"async\"></p>\n<p>系统将提示您输入密码：</p>\n<p><img alt=\"IDE 密码\" src=\"assets/docs/introduction/setup/visual-studio-01.png\" loading=\"lazy\" decoding=\"async\"></p>\n<p>输入输出中 <strong>IdePassword</strong> 字段中的值，Web IDE 将加载。</p>\n<p><img alt=\"代码服务器登录画面\" src=\"assets/docs/introduction/setup/vscode-splash.webp\" loading=\"lazy\" decoding=\"async\"></p>\n<p>按 <strong>开始</strong> 访问工作坊启动页面：</p>\n<p><img alt=\"开始\" src=\"assets/docs/introduction/setup/workshop-event-page.webp\" loading=\"lazy\" decoding=\"async\"></p>"}, "_partials/setup/ide-cleanup": {"id": "_partials/setup/ide-cleanup", "path": "_partials/setup/ide-cleanup.mdx", "title": "Ide Cleanup", "module": "misc", "category": "Partials", "crumbs": ["Partials", "Ide Cleanup"], "prev": null, "prevTitle": null, "next": null, "nextTitle": null, "content": "<header><h1>Ide Cleanup</h1></header>\n<p>完成 EKS 集群的清理后，您可以删除 IDE CloudFormation 堆栈。</p>\n<p>导航到 <a href=\"https://console.aws.amazon.com/cloudformation/home\">CloudFormation 控制台</a> 并选择 <code>eks-workshop-ide</code> 堆栈，然后单击 <strong>删除</strong> 按钮：</p>", "html": "<header><h1>Ide Cleanup</h1></header>\n<p>完成 EKS 集群的清理后，您可以删除 IDE CloudFormation 堆栈。</p>\n<p>导航到 <a href=\"https://console.aws.amazon.com/cloudformation/home\">CloudFormation 控制台</a> 并选择 <code>eks-workshop-ide</code> 堆栈，然后单击 <strong>删除</strong> 按钮：</p>"}});
  if (window.__onChunkLoaded) { window.__onChunkLoaded('misc'); }
})();
